fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut low = 0;
    let mut high = v.len();

    while low < high {
        let mid = low + (high - low) / 2;
        if v[mid] < k {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    // At this point, low == high and v[low] == k (since k is guaranteed to be in v).
    low
}

