    #[test]
    fn finds_existing_elements() {
        let v = vec![1, 2, 2, 4, 5, 5, 7];
        assert_eq!(binary_search(&v, 1), 0);
        let idx2 = binary_search(&v, 2);
        assert!(idx2 == 1 || idx2 == 2);
        assert_eq!(binary_search(&v, 4), 3);
        let idx5 = binary_search(&v, 5);
        assert!(idx5 == 4 || idx5 == 5);
        assert_eq!(binary_search(&v, 7), 6);
    }
